// «Performance турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

let calls = 0;
function slowDouble(n) { calls = calls + 1; return n * 2; }

const fast = memoize(slowDouble);
window.R1 = fast(5);
window.R2 = fast(5);
window.R3 = fast(6);
window.CALLS = calls;

panel("ok", "res", "Memoize", ["fast(5)=" + window.R1, "fast(5)=" + window.R2 + " (кэш)", "fast(6)=" + window.R3, "slowDouble дуудлага: " + window.CALLS]);
document.body.dataset.ready = "1";

